function Pick({label,value,onChange,options}:{label:string;value:string;onChange:(v:string)=>void;options:(string|{value:string;label:string})[]}){return <label className="field"><span>{label}</span><Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label}><SelectValue/></SelectTrigger><SelectContent>{options.map(o=>{const v=typeof o==='string'?o:o.value;return <SelectItem key={v} value={v}>{typeof o==='string'?o:o.label}</SelectItem>})}</SelectContent></Select></label>}
function Field({label,children,hint}:{label:string;children:React.ReactNode;hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Pill({children,tone=''}:{children:React.ReactNode;tone?:string}){return <span className={'pill '+tone}>{children}</span>}
function Empty({title,text,action}:{title:string;text:string;action?:React.ReactNode}){return <div className="empty-state"><Layers/><h3>{title}</h3><p>{text}</p>{action}</div>}
function download(name:string,obj:unknown){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
// Phone-width bottom tab bar: the five main sections plus More (opens the full menu).
function MobileTabBar({tab,setTab,pending}:{tab:string;setTab:(name:string)=>void;pending:number}){const {setOpenMobile}=useSidebar();const main=NAV.slice(0,5);
 return <nav className="mobile-tabbar" aria-label="Main sections">{main.map(({name,icon:Icon})=><button key={name} type="button" aria-current={tab===name?'page':undefined} onClick={()=>setTab(name)}><Icon aria-hidden="true"/><span>{name}</span></button>)}<button type="button" aria-haspopup="dialog" onClick={()=>setOpenMobile(true)}><Ellipsis aria-hidden="true"/><span>More</span>{pending>0&&<span className="nav-count">{pending}</span>}</button></nav>}
function NavigationButton({onClick,...props}:React.ComponentProps<typeof SidebarMenuButton>){const {setOpenMobile}=useSidebar();return <SidebarMenuButton {...props} onClick={e=>{onClick?.(e);setOpenMobile(false)}}/>}
