 const propose=(type:Proposal['type'],input?:string)=>{const response=type==='load'?makeLoadProposal(s):null;const p=response?.proposal||(type==='load'?null:makeProposal(s,type,input));if(!p){toast.info(response?.error||'No workout in this plan can use that change yet.');return}if(!setState(v=>changed({...v,proposals:[p,...v.proposals]},'Created proposal: '+p.title)))return;setProposalError('');setProposalView(p)};
 const startWorkout=(target:Session|undefined=session)=>{if(!target)return;if(s.active){toast.info('Resume or finish your active workout before starting another.');setTab('Workout');return}const issue=eligibility(s,target);if(issue){toast.error(issue);setTab('Today');return}if(target.date!==day()){toast.info('This workout is on another date. Review moving it to today before you start.');openMove(target);setMoveDate(day());return}const collision=s.events.find(e=>e.date===target.date);if(collision){toast.error('A fixed commitment is on this date. Review the Calendar before training.');setTab('Calendar');return}const sets=startingSets(s,target.items);if(!setState(v=>changed({...v,active:{id:uid('workout'),sessionId:target.id,title:target.title,date:day(),startedAt:Date.now(),sets,targets:target.items.map(i=>({...i})),loadContext:{...s.loadContext}}},'Started '+target.title)))return;setTab('Workout')};
 const activeBase=plan?.sessions.find(x=>x.id===s.active?.sessionId);const activeSession=activeBase?{...activeBase,items:s.active?.targets||activeBase.items}:undefined;
