 const logSet=(index:number,seconds:number)=>{const w=currentState.current.active;if(!w)return;const log=w.sets[index];if(!log||log.done)return;const error=completedSetError(log.reps,log.kg,exFor(log.exerciseId,s.custom).metric);if(error){toast.error(error);return}prepareRestSound();if(setState(v=>logWorkoutSet(v,index,seconds)))toast.success('Set saved.');};

 const finishWorkout=(skip=false)=>{const w=s.active;if(!w)return;const bad=w.sets.find(x=>x.done&&(!Number.isFinite(x.reps)||x.reps<=0||x.reps>9999||(exFor(x.exerciseId,s.custom).metric==='reps'&&!Number.isInteger(x.reps))||(x.kg!==null&&(!Number.isFinite(x.kg)||x.kg<0||x.kg>1500))));if(bad){setFeedback(false);setTab('Workout');toast.error(exFor(bad.exerciseId,s.custom).name+' · set '+bad.set+': enter a valid amount or clear Done. Your workout is still open.');return}if(!w.sets.some(x=>x.done)){if(['yes','unsure'].includes(symptom)){if(!setState(v=>changed({...v,hold:true,active:null},'Concern saved. No completed sets were added.')))return;setFeedback(false);setTab('Today');toast.info('Concern saved. No completed sets were added.');return}toast.error('Log at least one completed set or interval before finishing.');return}const partial=!w.sets.every(x=>x.done);let next:State=changed({...s,active:null,loadContext:{...s.loadContext,...w.loadContext},history:[{...w,finishedAt:Date.now(),partial,supervisorConfirmed,effort:skip?'unsure':effort,symptom:['yes','unsure'].includes(symptom)?symptom:skip?'skip':symptom,rating:skip?undefined:Number(rating)||undefined},...s.history],plan:plan?{...plan,sessions:plan.sessions.map(x=>x.id===w.sessionId?{...x,status:partial?'partial':'completed'}:x)}:null},'Saved '+(partial?'partial':'completed')+' workout: '+w.title);
 if(symptom==='yes'||symptom==='unsure')next=changed({...next,hold:true},'Automated recommendations held after symptom report.');
 else if(!skip&&['harder','easier'].includes(effort)){const p=makeProposal(next,effort==='harder'?'sets':'load');if(p)next={...next,proposals:[p,...next.proposals]}}
 if(!setS(next))return;setFeedback(false);if(!setS(v=>({...v,restTimer:null})))return;setTab('Today');toast.success('Workout saved. Any suggested changes wait for your approval.');};
 const commitProposal=(p:Proposal)=>{const r=applyProposal(s,p.id);if(!setS(r.state))return;if(r.error){setProposalError(r.error);setProposalView(r.state.proposals.find(x=>x.id===p.id)||null)}else{toast.success('Change accepted. Completed history is unchanged.');setProposalError('');setProposalView(null)}};
