 const demoAction=(type:string)=>{const demo=type==='youth'?{...blankProfile,name:'Alex',age:15,goal:'sport',mode:'app' as const,supervision:true,equipment:'Dumbbells',days:[1,4],weeks:8,minutes:40,start:day()}:type==='run'?{...blankProfile,name:'Alex',goal:'running',days:[1,3,5],weeks:9,minutes:40,start:day()}:{...blankProfile,name:'Alex',age:16,goal:'sport',mode:'coach' as const,season:'In-season',start:day()};setProfile(demo);setResumeSetup(false);setBuilder(true)};
 const sourceCards=(ids:string[])=>ids.map(id=>{const src=SOURCE_LINKS[id];return src?<a className="source-card" href={src.url} key={id} target="_blank" rel="noopener noreferrer"><div><b>{src.name}</b><p>{src.summary}</p></div><ExternalLink size={17}/></a>:null});
