 const coachingControls=<div className="today-adjustments"><div><p className="eyebrow">A QUICK CHECK-IN</p><h3>Does your next session need a change?</h3><p className="muted">Tell us what changed. You choose whether to change the plan.</p></div><div className="adjustment-buttons"><Button variant="outline" disabled={!session||!!s.active||s.hold||plan?.profile.mode!=='app'} onClick={()=>propose('sets')}>Last session felt harder</Button><Button variant="outline" disabled={!session||!!s.active||s.hold||plan?.profile.mode!=='app'} onClick={()=>propose('load')}>Work felt easier</Button><Button variant="outline" disabled={!session||!!s.active} onClick={()=>session&&setInspectSession(session)}>Equipment unavailable?</Button><Button variant="outline" disabled={!session||!!s.active} onClick={()=>openMove()}>Move a workout</Button><Button variant="outline" disabled={!session||!!s.active||s.hold||plan?.profile.mode!=='app'} onClick={()=>setReturnOpen(true)}>Returning after a break</Button><Button variant="outline" disabled={!plan} onClick={()=>{if(!setState(v=>changed({...v,hold:true},'Concern reported from Today.')))return;toast.info('Recommendations are on hold. Your workout records remain available.')}}>Report pain or a concern</Button></div>{plan?.profile.mode!=='app'&&<p className="small-copy">Your coach’s or your own targets stay under your control. Schedule changes remain available.</p>}</div>;
