 if(storageBlocked&&!sampleMode)return <>{transferDialogs}<SavedDataRecovery keyMissing={keyMissing} detail={keyMissing?'':storageError} onExport={()=>{const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([rawSaved.current],{type:'application/octet-stream'}));link.download='movefield-locked-file.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}} onRestore={()=>setRestoreOpen(true)} onSample={exploreSample} onReset={async()=>{try{await getVault()?.reset()}catch{}rawSaved.current='';if(!setS(freshState()))return;setKeyMissing(false);setStorageBlocked(false);setStorageError('');setEntry(true)}}/></>;
